<?php require __DIR__.'/../lib/bootstrap.php';$key=$_SERVER['HTTP_X_API_KEY']??'';if(!$CONFIG['api_key']||!hash_equals($CONFIG['api_key'],$key))json_out(['error'=>'Unauthorized'],401);$in=json_decode(file_get_contents('php://input'),true)?:[];$iccid=trim($in['iccid']??$CONFIG['iccid']);$body=trim($in['message']??'');if(!$iccid||!$body)json_out(['error'=>'iccid and message required'],422);try{$r=send_sms($iccid,$body);$id=add_row('messages',['iccid'=>$iccid,'body'=>$body,'status'=>'sent','response'=>$r,'created_at'=>date('c')]);json_out(['success'=>true,'id'=>$id,'provider'=>$r]);}catch(Throwable $e){json_out(['success'=>false,'error'=>$e->getMessage()],502);}